import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { useLocalization } from '@/context/LocalizationContext';
import { useBuilderStore } from '@/hooks';
import { useAiActions } from '@/hooks/report-mode/use-ai-actions';
import { cn } from '@/lib/utils/cn';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical, Link as LinkIcon, Loader2, Sparkles } from 'lucide-react';
import React from 'react';
import { Checkbox } from '../../ui/checkbox';
import { Section, type Project } from '@/lib/types';

interface SectionAccordionItemProps {
    section: Section;
    chapterIndex: number;
    sectionIndex: number;
    isProjectBuildMode: boolean;
    isSelected: boolean;
    isActive: boolean;
    onActivate: (sectionId: string) => void;
    toggleSectionSelection: (sectionId: string) => void;
}

export function SectionAccordionItem({
    section,
    chapterIndex,
    sectionIndex,
    isProjectBuildMode,
    isSelected,
    isActive,
    onActivate,
    toggleSectionSelection,
}: SectionAccordionItemProps) {
    const { t } = useLocalization();
    const { userProfile, project } = useBuilderStore();

    const { generateSectionMutation, generateChapterMutation, generateProjectMutation } = useAiActions();

    const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: section.id });

    const style: React.CSSProperties = {
        transform: CSS.Transform.toString(transform),
        transition,
        zIndex: isDragging ? 2 : 0,
        position: 'relative',
    };

    if (!section) return null;

    const isGenerating = generateSectionMutation?.isPending && generateSectionMutation.variables === section.id;
    const isAnythingGenerating = generateSectionMutation?.isPending || generateChapterMutation.isPending || generateProjectMutation.isPending;
    const hasCredits = (userProfile?.credits ?? 0) >= 1;
    const canGenerate = hasCredits && !isAnythingGenerating;

    function handleGenerateClick(e: React.MouseEvent) {
        e.stopPropagation();
        if (canGenerate) {
            generateSectionMutation.mutate(section.id);
        }
    }

    const getContextNames = (proj: Project | null, sec: Section): string[] => {
        if (!proj || !sec.context) return [];

        const sectionNames = Object.keys(sec.context.sections || {}).map(id => proj?.getSection(id)?.title || 'Untitled Section');
        const fileNames = Object.keys(sec.context.externalContext || {}).map(id => proj?.externalContext?.find(f => f.id === id)?.fileName || 'Untitled File');

        return [...sectionNames, ...fileNames];
    };

    const contextNames = getContextNames(project, section);
    const totalContext = contextNames.length;

    const handleActivate = () => onActivate(section.id);

    return (
        <div
            ref={setNodeRef}
            style={style}
            {...attributes}
            className={cn(
                "bg-background border rounded-lg overflow-hidden shadow-sm transition-shadow",
                isActive && "ring-2 ring-primary/30 shadow-md"
            )}
        >
            <div
                className={cn(
                    "flex flex-wrap items-center gap-2 px-4 py-3 bg-muted/10 border-b cursor-pointer",
                    isActive && "bg-primary/5"
                )}
                onClick={handleActivate}
            >
                {isProjectBuildMode && (
                    <div className="flex items-center gap-2" onClick={(e) => { e.stopPropagation(); toggleSectionSelection(section.id); }}>
                        <Checkbox
                            checked={isSelected}
                            aria-label={`Select section ${section.title}`}
                        />
                    </div>
                )}
                <div className="flex flex-wrap items-center gap-3 flex-1 min-w-0 group">
                    <div {...listeners} className="p-1.5 rounded-md cursor-grab touch-none -ml-2 flex items-center gap-2 text-muted-foreground transition-colors hover:bg-muted/40 shrink-0">
                        <span className="text-[11px] w-8 text-left">{chapterIndex >= 0 ? `${chapterIndex + 1}.${sectionIndex + 1}` : `${sectionIndex + 1}`}</span>
                        <GripVertical className="h-5 w-5" />
                    </div>
                    {isGenerating && <Loader2 className="h-4 w-4 animate-spin shrink-0" />}
                    <span className="text-sm font-medium p-0 h-auto truncate break-words group-hover:text-foreground min-w-0">
                        {section.title}
                    </span>
                    {totalContext > 0 && (
                        <TooltipProvider>
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center gap-1 ml-2 rounded-full border border-primary/20 bg-primary/10 px-2 py-0.5 text-primary shrink-0">
                                        <LinkIcon className="h-3.5 w-3.5" />
                                        <span className="text-[11px] font-medium">{totalContext}</span>
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent side="top">
                                    <div className="text-xs space-y-1">
                                        {contextNames.map(name => <p key={name}>{name}</p>)}
                                    </div>
                                </TooltipContent>
                            </Tooltip>
                        </TooltipProvider>
                    )}
                </div>
            </div>
            <div className="p-4 border-t border-border/60 bg-muted/20">
                <TooltipProvider>
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                onClick={handleGenerateClick}
                                disabled={!canGenerate}
                                className='w-full'
                            >
                                {isGenerating ? <Loader2 className="me-2 h-4 w-4 animate-spin" /> : <Sparkles className="me-2 h-4 w-4" />}
                                {t('builder.reportGenerator.generateButton')}
                            </Button>
                        </TooltipTrigger>
                        {!canGenerate && (
                            <TooltipContent>
                                <p>{isAnythingGenerating ? "Another generation is in progress." : "Insufficient credits."}</p>
                            </TooltipContent>
                        )}
                    </Tooltip>
                </TooltipProvider>
            </div>
        </div>
    );
};
"}

{"file_path":"src/components/report-mode/generation-tools/SortableChapterItem.tsx","overwrite":true,"initial_content":"'use client';

import { Button } from '@/components/ui/button';
import { Chapter } from '@/lib/types';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import {
  GripVertical,
  PlusCircle,
} from 'lucide-react';
import React, { useMemo } from 'react';
import { Checkbox } from "../../ui/checkbox";
import { SectionAccordionItem } from './SectionAccordionItem';
import { useBuilderStore } from "@/hooks";

interface SortableChapterItemProps {
  chapter: Chapter;
  index: number;
  isProjectBuildMode: boolean;
  selectedSectionsForBuild: Set<string>;
  toggleChapterSelection: (chapterId: string, select: boolean) => void;
  toggleSectionSelection: (sectionId: string) => void;
  activeSectionId: string | null;
  onActivateSection: (sectionId: string) => void;
}

export function SortableChapterItem({
  chapter,
  index,
  isProjectBuildMode,
  selectedSectionsForBuild,
  toggleChapterSelection,
  toggleSectionSelection,
  activeSectionId,
  onActivateSection,
}: SortableChapterItemProps) {
    const { 
        updateProject
    } = useBuilderStore(state => ({
        updateProject: state.updateProject,
    }));

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: chapter.id });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 2 : 0,
    position: 'relative',
  };

  const sectionsInChapter = chapter.sections;
  const isAllSectionsSelected = useMemo(() => {
    if (sectionsInChapter.length === 0) return false;
    return sectionsInChapter.every(s => selectedSectionsForBuild.has(s.id));
  }, [sectionsInChapter, selectedSectionsForBuild]);

  const isSomeSectionsSelected = useMemo(() => {
    if (sectionsInChapter.length === 0) return false;
    const hasSelected = sectionsInChapter.some(s => selectedSectionsForBuild.has(s.id));
    return hasSelected && !isAllSectionsSelected;
  }, [sectionsInChapter, selectedSectionsForBuild, isAllSectionsSelected]);

  const handleAddSection = (chapterId: string) => {
    updateProject(p => p.addSectionToChapter(chapterId, 'Untitled Section'));
  }

  return (
    <div ref={setNodeRef} style={style} {...attributes}>
      <div className="bg-card border rounded-lg shadow-sm overflow-hidden">
        <div className="flex items-center px-4 py-3 bg-muted/10 border-b">
          {isProjectBuildMode && (
            <div className="flex items-center gap-2 mr-2">
              <Checkbox
                id={`select-chapter-${chapter.id}`}
                checked={isAllSectionsSelected}
                aria-checked={isSomeSectionsSelected ? 'mixed' : isAllSectionsSelected}
                onCheckedChange={(checked) => toggleChapterSelection(chapter.id, !!checked)}
                aria-label={`Select all sections in chapter ${chapter.title}`}
              />
            </div>
          )}
          <div className="flex-1 py-0">
            <div className="flex items-center gap-3 flex-1 min-w-0 group">
              {listeners && (
                <div {...listeners} className="p-1.5 rounded-md cursor-grab touch-none -ml-2 flex items-center gap-2 text-muted-foreground transition-colors hover:bg-muted/40">
                  <span className="text-xs w-5 text-center font-semibold">{index + 1}.</span>
                  <GripVertical className="h-5 w-5" />
                </div>
              )}
              <span className="text-base font-semibold tracking-tight truncate p-0 h-auto flex-1 text-left min-w-0">
                {chapter.title}
              </span>
            </div>
          </div>
        </div>
        <div className="border-t border-border/60 px-4 py-4 space-y-4 bg-background">
          <div className="w-full space-y-2">
            {chapter.sections.map((section, sectionIndex) => (
              <SectionAccordionItem
                key={section.id}
                section={section}
                sectionIndex={sectionIndex}
                chapterIndex={index}
                isProjectBuildMode={isProjectBuildMode}
                isSelected={selectedSectionsForBuild.has(section.id)}
                toggleSectionSelection={toggleSectionSelection}
                isActive={activeSectionId === section.id}
                onActivate={onActivateSection}
              />
            ))}
          </div>
          <Button size="sm" variant="outline" onClick={() => handleAddSection(chapter.id)} className="w-full">
            <PlusCircle className="me-2 h-4 w-4" />
            Add New Section
          </Button>
        </div>
      </div>
    </div>
  );
};
"}

