'use client';

import { useLocalization } from '@/context/LocalizationContext';
import { cn } from '@/lib/utils/cn';
import { BookOpenText, Settings, SlidersHorizontal, Languages as LanguageIcon, MessageSquare, ZoomOut, ZoomIn, PanelRightClose, PanelRightOpen } from 'lucide-react';
import React, { Suspense, lazy, useState } from 'react';
import { Button } from '../ui/button';
import { CollapsibleSidePanel } from '../ui/CollapsibleSidePanel';
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from '@/components/ui/resizable';
import { BuilderPageSkeleton } from '@/app/builder/loading';
import { OnboardingGuide } from '@/components/onboarding/OnboardingGuide';
import { Input } from '@/components/ui/input';
import { formatDistanceToNow } from 'date-fns';
import { SessionActions } from '@/components/report-mode/session/SessionActions';
import { useReportGenerator } from '@/hooks/report-mode/useReportGenerator';
import { Slider } from '../ui/slider';
import { Label } from '../ui/label';
import { Badge } from '../ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '../ui/popover';
import { ToneSchema } from '@/lib/types';
import type { Language, Tone } from '@/lib/types';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '../ui/tooltip';
import { ProjectChat } from './chat/ProjectChat';
import { SectionTabsPanel } from './generation-tools/SectionTabsPanel';
import { ProjectProperties } from '@/lib/types';

const ReportResults = lazy(() => import('./ReportResults'));

function ReportSkeleton() {
    return (
        <div className="flex h-full items-center justify-center">
            <div className="text-center">
                <div className="h-10 w-10 animate-spin rounded-full border-4 border-primary border-t-transparent mx-auto" />
                <p className="mt-4 text-muted-foreground">Loading content...</p>
            </div>
        </div>
    );
}

function BottomNavBar({ activeView, setActiveView }: { activeView: 'generator' | 'result', setActiveView: (view: 'generator' | 'result') => void }) {
    return (
        <div className="fixed bottom-0 left-0 right-0 h-16 bg-background border-t p-2 flex items-center justify-around z-50 lg:hidden">
            <Button variant={activeView === 'generator' ? 'secondary' : 'ghost'} onClick={() => setActiveView('generator')} className="flex flex-col h-auto py-2">
                <Settings className="h-5 w-5" />
                <span className="text-xs">Tools</span>
            </Button>
            <Button variant={activeView === 'result' ? 'secondary' : 'ghost'} onClick={() => setActiveView('result')} className="flex flex-col h-auto py-2">
                <BookOpenText className="h-5 w-5" />
                <span className="text-xs">Result</span>
            </Button>
        </div>
    );
}

export default function ReportModeGenerator({ initialProject }: { initialProject?: ProjectProperties | null }) {
    const {
        locale,
        isMobile,
        activeMobileView,
        setActiveMobileView,
        activePanelKey,
        setActivePanelKey,
        showOnboarding,
        setShowOnboarding,
        handleOnboardingComplete,
        project,
        isStoreInitialized,
        updateProjectName,
        updateProject,
        isSaving,
        panels,
        isChatOpen,
        setIsChatOpen,
        zoomLevel,
        setZoomLevel,
        activeSectionId,
    } = useReportGenerator(initialProject);

    const activeSection = activeSectionId ? project?.getSection(activeSectionId) ?? null : null;
    const showSectionTabs = activePanelKey === 'generate';
    const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);

    const reportPanelContent = showSectionTabs ? (
        <div className="h-full grid grid-cols-1 xl:grid-cols-[minmax(0,1fr)_360px] gap-4">
            <ReportResults activePanelKey={activePanelKey} />
            {isRightSidebarOpen ? (
                <SectionTabsPanel section={activeSection} className="h-full" />
            ) : (
                <div className="hidden xl:flex items-start justify-end">
                    <Button
                        variant="outline"
                        size="sm"
                        className="gap-2"
                        onClick={() => setIsRightSidebarOpen(true)}
                    >
                        <PanelRightOpen className="h-4 w-4" />
                        Show Details
                    </Button>
                </div>
            )}
        </div>
    ) : (
        <ReportResults activePanelKey={activePanelKey} />
    );

    // States removed as Popover handles its own open state or can be controlled if needed.
    // However, keeping them if we want to synchronize with tooltips or other logic.
    const [isControlsPanelOpen, setIsControlsPanelOpen] = useState(false);
    const [isLanguagePanelOpen, setIsLanguagePanelOpen] = useState(false);


    const handleComplexityChange = (value: number) => {
        if (project) {
          updateProject(p => p.with({ complexity: value }));
        }
    };

    const handleFormalityChange = (value: number) => {
        if (project) {
          updateProject(p => p.with({ formality: value }));
        }
    };

    const handleLanguageChange = (value: Language) => {
        if (project) {
          updateProject(p => p.with({ language: value }));
        }
    };

    const handleToneChange = (value: string) => {
        if (project) {
          updateProject(p => p.with({ tone: value as Tone }));
        }
    };

    const handleZoomIn = () => setZoomLevel(prev => Math.min(2, prev + 0.1));
    const handleZoomOut = () => setZoomLevel(prev => Math.max(0.5, prev - 0.1));
    const handleZoomReset = () => setZoomLevel(1);

    if (!isStoreInitialized || !project) {
        return <BuilderPageSkeleton />;
    }

    return (
        <div className="relative flex-grow flex flex-col">
            <OnboardingGuide isOpen={showOnboarding} onOpenChange={setShowOnboarding} onComplete={handleOnboardingComplete} />

            {/* Ensure tabs don't show for missing section */}
            {/* Global Controls Floating UI - LEFT */}
            <div className="fixed bottom-6 left-6 z-20 hidden lg:flex items-end gap-3">
                <Popover open={isControlsPanelOpen} onOpenChange={setIsControlsPanelOpen}>
                    <TooltipProvider>
                        <Tooltip>
                            <PopoverTrigger asChild>
                                <TooltipTrigger asChild>
                                    <Button
                                        size="icon"
                                        className="h-12 w-12 rounded-full shadow-md bg-background/90 backdrop-blur-sm border border-border/60"
                                        aria-label="Toggle global controls"
                                    >
                                        <SlidersHorizontal className="h-5 w-5" />
                                    </Button>
                                </TooltipTrigger>
                            </PopoverTrigger>
                            <TooltipContent side="right"><p>Complexity & Formality</p></TooltipContent>
                        </Tooltip>
                    </TooltipProvider>
                    <PopoverContent side="top" align="start" className="w-64 p-4 mb-2 bg-background/90 backdrop-blur-sm border border-border/60 shadow-lg">
                        <div className="space-y-6">
                            {/* Formality Slider */}
                            <div className="space-y-2">
                                <div className="flex justify-between items-center">
                                    <Label className="text-xs font-semibold tracking-wider uppercase">Formality</Label>
                                    <Badge variant="secondary">{project.formality ?? 70}%</Badge>
                                </div>
                                <Slider
                                    value={[project.formality ?? 70]}
                                    onValueChange={(val) => handleFormalityChange(val[0])}
                                    min={0}
                                    max={100}
                                    step={10}
                                />
                            </div>
                            {/* Complexity Slider */}
                            <div className="space-y-2">
                            <div className="flex justify-between items-center">
                                    <Label className="text-xs font-semibold tracking-wider uppercase">Complexity</Label>
                                    <Badge variant="secondary">{project.complexity ?? 50}%</Badge>
                                </div>
                                <Slider
                                    value={[project.complexity ?? 50]}
                                    onValueChange={(val) => handleComplexityChange(val[0])}
                                    min={0}
                                    max={100}
                                    step={10}
                                />
                            </div>
                        </div>
                    </PopoverContent>
                </Popover>

                <Popover open={isLanguagePanelOpen} onOpenChange={setIsLanguagePanelOpen}>
                    <TooltipProvider>
                        <Tooltip>
                            <PopoverTrigger asChild>
                                <TooltipTrigger asChild>
                                    <Button
                                        size="icon"
                                        className="h-12 w-12 rounded-full shadow-md bg-background/90 backdrop-blur-sm border border-border/60"
                                        aria-label="Toggle language controls"
                                    >
                                        <LanguageIcon className="h-5 w-5" />
                                    </Button>
                                </TooltipTrigger>
                            </PopoverTrigger>
                            <TooltipContent side="right"><p>Language & Tone</p></TooltipContent>
                        </Tooltip>
                    </TooltipProvider>
                    <PopoverContent side="top" align="start" className="w-64 p-4 mb-2 bg-background/90 backdrop-blur-sm border border-border/60 shadow-lg">
                        <div className="space-y-6">
                            {/* Language Select */}
                            <div className="space-y-2">
                                <Label className="text-xs font-semibold tracking-wider uppercase">Language</Label>
                                <Select value={project.language} onValueChange={(val) => handleLanguageChange(val as Language)}>
                                    <SelectTrigger>
                                        <SelectValue placeholder="Select a language" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {Object.values(ToneSchema).map((lang) => (
                                            <SelectItem key={lang} value={lang}>{lang}</SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                            {/* Tone Select */}
                            <div className="space-y-2">
                                <Label className="text-xs font-semibold tracking-wider uppercase">Tone</Label>
                                <Select value={project.tone} onValueChange={(val) => handleToneChange(val)}>
                                    <SelectTrigger>
                                        <SelectValue placeholder="Select a tone" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {Object.values(ToneSchema).map((tone) => (
                                            <SelectItem key={tone} value={tone}>{tone}</SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                    </PopoverContent>
                </Popover>
            </div>

            {/* Floating Chat Button - RIGHT */}
            <div className="fixed bottom-6 right-6 z-20 hidden lg:block">
                <TooltipProvider>
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                size="icon"
                                className="h-12 w-12 rounded-full shadow-md bg-primary text-primary-foreground"
                                onClick={() => setIsChatOpen(true)}
                                aria-label="Open AI Chat"
                            >
                                <MessageSquare className="h-5 w-5" />
                            </Button>
                        </TooltipTrigger>
                        <TooltipContent side="left"><p>AI Chat Assistant</p></TooltipContent>
                    </Tooltip>
                </TooltipProvider>
            </div>

            {/* Main Content */}
            <div className="flex flex-col flex-grow">
                {/* Top Bar */}
                <div className="flex items-center justify-between border-b border-border/60 bg-background/90 backdrop-blur-sm px-4 py-2">
                    <div className="flex items-center gap-3">
                        <Input
                            value={project.name}
                            onChange={(e) => updateProjectName(e.target.value)}
                            className="w-60"
                            placeholder="Project Name"
                        />
                        {isSaving && (
                            <span className="text-xs text-muted-foreground">Saving...</span>
                        )}
                    </div>
                    <div className="flex items-center gap-2">
                        <Button variant="ghost" size="icon" onClick={handleZoomOut}>
                            <ZoomOut className="h-4 w-4" />
                        </Button>
                        <span className="text-sm w-10 text-center">{Math.round(zoomLevel * 100)}%</span>
                        <Button variant="ghost" size="icon" onClick={handleZoomIn}>
                            <ZoomIn className="h-4 w-4" />
                        </Button>
                        <Button variant="ghost" size="icon" onClick={handleZoomReset}>
                            <span className="text-xs">100%</span>
                        </Button>
                        {showSectionTabs && (
                            <Button
                                variant="outline"
                                size="icon"
                                onClick={() => setIsRightSidebarOpen(prev => !prev)}
                                aria-label={isRightSidebarOpen ? 'Collapse right sidebar' : 'Expand right sidebar'}
                            >
                                {isRightSidebarOpen ? (
                                    <PanelRightClose className="h-4 w-4" />
                                ) : (
                                    <PanelRightOpen className="h-4 w-4" />
                                )}
                            </Button>
                        )}
                        <SessionActions isSaving={false} />
                    </div>
                </div>

                <div className="flex flex-col flex-grow">
                     <div className="pb-16 lg:pb-0 flex-grow">
                        <Suspense fallback={<ReportSkeleton />}>
                            <div className="h-full" dir={locale === 'ar' ? 'rtl' : 'ltr'}>
                                {isMobile ? (
                                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start h-full">
                                        <div className={cn(
                                            "lg:col-span-4 xl:col-span-4 h-full",
                                            isMobile && activeMobileView !== 'generator' && "hidden"
                                        )}>
                                            <CollapsibleSidePanel
                                                panels={panels}
                                                activeKey={activePanelKey}
                                                onActiveKeyChange={setActivePanelKey}
                                            />
                                        </div>
                                        <div className={cn(
                                            "lg:col-span-8 xl:col-span-8 h-full",
                                            isMobile && activeMobileView !== 'result' && "hidden"
                                        )}>
                                            {reportPanelContent}
                                        </div>
                                    </div>
                                ) : (
                                    <ResizablePanelGroup direction="horizontal" className="h-full">
                                        <ResizablePanel defaultSize={35} minSize={28} maxSize={45}>
                                            <div className="h-full">
                                                <CollapsibleSidePanel
                                                    panels={panels}
