{"file_path":"src/components/ui/CollapsibleSidePanel.tsx","overwrite":true,"initial_content":"'use client';

import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { useMobile } from '@/hooks';
import { cn } from '@/lib/utils/cn';
import { PanelLeftClose, PanelLeftOpen } from 'lucide-react';
import { type ReactElement, type ReactNode } from 'react';

export interface PanelItem {
  key: string;
  title: string;
  description?: string;
  icon: ReactElement;
  content: ReactNode;
}

interface CollapsibleSidePanelProps {
  panels: PanelItem[];
  activeKey: string;
  onActiveKeyChange: (key: string) => void;
  isExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  className?: string;
}

export function CollapsibleSidePanel({
  panels,
  activeKey,
  onActiveKeyChange,
  isExpanded = true,
  onExpandedChange,
  className,
}: CollapsibleSidePanelProps) {
  const isMobile = useMobile();
  const activePanel = panels.find((p) => p.key === activeKey) ?? panels[0];
  const showExpandedRail = isMobile || isExpanded;

  if (!panels || panels.length === 0 || !activePanel) {
    return null;
  }

  const handleToggleExpanded = () => {
    onExpandedChange?.(!isExpanded);
  };

  const navigation = (
    <TooltipProvider>
      {panels.map((panel) => {
        const isActive = activeKey === panel.key;

        const button = (
          <Button
            variant="ghost"
            onClick={() => onActiveKeyChange(panel.key)}
            aria-label={panel.title}
            aria-pressed={isActive}
            className={cn(
              'group h-10 justify-start gap-3 rounded-lg border border-transparent px-3 text-muted-foreground transition-all hover:border-border/60 hover:bg-muted/50 hover:text-foreground',
              showExpandedRail ? 'w-full' : 'h-10 w-10 px-0 justify-center',
              isActive && 'border-primary/20 bg-primary/10 text-primary hover:bg-primary/15 hover:text-primary'
            )}
          >
            <span className="shrink-0">{panel.icon}</span>
            {showExpandedRail && (
              <span className="min-w-0 truncate text-sm font-medium">{panel.title}</span>
            )}
          </Button>
        );

        if (showExpandedRail) {
          return <div key={panel.key}>{button}</div>;
        }

        return (
          <Tooltip key={panel.key} delayDuration={0}>
            <TooltipTrigger asChild>{button}</TooltipTrigger>
            <TooltipContent side="right">
              <p>{panel.title}</p>
            </TooltipContent>
          </Tooltip>
        );
      })}
    </TooltipProvider>
  );

  return (
    <div
      className={cn(
        'self-start flex h-full min-h-0 overflow-hidden rounded-xl border bg-background shadow-sm',
        isMobile && 'mb-16 flex-col',
        className
      )}
    >
      <div
        className={cn(
          'shrink-0 border-border/60 bg-muted/10',
          isMobile ? 'border-b p-3' : 'border-r p-2 transition-[width] duration-200 ease-out',
          !isMobile && (showExpandedRail ? 'w-64' : 'w-14')
        )}
      >
        <div className={cn('flex gap-2', isMobile ? 'grid grid-cols-2' : 'flex-col')}>
          {!isMobile && (
            <Button
              variant="ghost"
              size="icon"
              onClick={handleToggleExpanded}
              aria-label={isExpanded ? 'Collapse sidebar' : 'Expand sidebar'}
              aria-expanded={isExpanded}
              className="mb-1 h-10 w-10 self-start rounded-lg"
            >
              {isExpanded ? <PanelLeftClose className="h-4 w-4" /> : <PanelLeftOpen className="h-4 w-4" />}
            </Button>
          )}
          {navigation}
        </div>
      </div>

      <div className="flex min-w-0 flex-1 flex-col">
        <div className="px-4 py-4 sm:px-5">
          <div className="space-y-1">
            <h2 className="text-sm font-semibold tracking-tight text-foreground sm:text-base">
              {activePanel.title}
            </h2>
            {activePanel.description && (
              <p className="text-xs text-muted-foreground sm:text-sm">
                {activePanel.description}
              </p>
            )}
          </div>
        </div>
        <Separator />
        <div className="min-w-0 flex-1 overflow-auto p-4 sm:p-5">
          {activePanel.content}
        </div>
      </div>
    </div>
  );
}
"}

