'use client';

import { useLocalization } from '@/context/LocalizationContext';
import { toast, useBuilderStore } from '@/hooks';
import { useMemo, useState, useCallback } from 'react';
import type { DragEndEvent } from '@dnd-kit/core';
import { useAiActions } from './use-ai-actions';

export function useReportGenerationTools() {
    const { t } = useLocalization();
    const { project, updateProject } = useBuilderStore();

    const [isBuildProjectDialogOpen, setIsBuildProjectDialogOpen] = useState(false);
    const [isProjectBuildMode, setIsProjectBuildMode] = useState(false);
    const [selectedSectionsForBuild, setSelectedSectionsForBuild] = useState<Set<string>>(new Set());

    const { generateProjectMutation } = useAiActions();

    const enterProjectBuildMode = useCallback(() => setIsProjectBuildMode(true), []);
    const exitProjectBuildMode = useCallback(() => {
        setIsProjectBuildMode(false);
        setSelectedSectionsForBuild(new Set());
    }, []);

    const toggleSectionSelection = useCallback((sectionId: string) => {
        setSelectedSectionsForBuild((prev) => {
            const next = new Set(prev);
            if (next.has(sectionId)) next.delete(sectionId);
            else next.add(sectionId);
            return next;
        });
    }, []);

    const toggleChapterSelection = useCallback((chapterId: string, select: boolean) => {
        if (!project) return;
        const chapter = project.getChapter(chapterId);
        if (!chapter) return;

        setSelectedSectionsForBuild((prev) => {
            const next = new Set(prev);
            chapter.sections.forEach((section) => {
                if (select) next.add(section.id);
                else next.delete(section.id);
            });
            return next;
        });
    }, [project]);

    const toggleSelectAll = useCallback((select: boolean) => {
        if (!project) return;
        if (select) {
            setSelectedSectionsForBuild(new Set(project.sections.map((section) => section.id)));
            return;
        }
        setSelectedSectionsForBuild(new Set());
    }, [project]);

    const handleAddChapter = useCallback(() => {
        updateProject((draft) => draft.addChapter());
        toast({ title: 'Chapter Created', description: 'A new untitled chapter has been added.' });
    }, [updateProject]);

    const handleAddSection = useCallback((chapterId: string) => {
        updateProject((draft) => draft.addSectionToChapter(chapterId, 'Untitled Section'));
        toast({ title: 'Section Created', description: 'A new untitled section has been added.' });
    }, [updateProject]);

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const { active, over } = event;
        if (!over || !project) return;
        const activeId = active.id.toString();
        const overId = over.id.toString();
        if (activeId === overId) return;

        updateProject((draft) => draft.moveContentItem(activeId, overId));
    }, [project, updateProject]);

    const chaptersToBuild = useMemo(() => {
        if (!project) return [];
        return project.chapters
          .map((chapter) => chapter.with({ sections: chapter.sections.filter((section) => selectedSectionsForBuild.has(section.id)) }))
          .filter((chapter) => chapter.sections.length > 0);
    }, [project, selectedSectionsForBuild]);

    const onGenerateProject = useCallback(() => {
        if (project && selectedSectionsForBuild.size > 0) {
          generateProjectMutation.mutate({ project, selectedSectionIds: selectedSectionsForBuild });
          setIsBuildProjectDialogOpen(false);
        }
    }, [project, selectedSectionsForBuild, generateProjectMutation]);

    const totalSelectableSections = project?.sections.length ?? 0;
    const selectedSectionsCount = selectedSectionsForBuild.size;
    const isAllSelected = totalSelectableSections > 0 && selectedSectionsCount === totalSelectableSections;
    const isIndeterminate = selectedSectionsCount > 0 && !isAllSelected;
    const canBuildProject = Boolean(project && project.content.length > 0);

    return {
        t,
        project,
        handleAddChapter,
        handleAddSection,
        handleDragEnd,
        isBuildProjectDialogOpen,
        setIsBuildProjectDialogOpen,
        isProjectBuildMode,
        enterProjectBuildMode,
        exitProjectBuildMode,
        selectedSectionsForBuild,
        selectedSectionsCount,
        totalSelectableSections,
        isAllSelected,
        isIndeterminate,
        toggleChapterSelection,
        toggleSectionSelection,
        toggleSelectAll,
        onGenerateProject,
        projectMutation: generateProjectMutation,
        chaptersToBuild,
        canBuildProject,
    };
}

export type ReportGenerationToolsController = ReturnType<typeof useReportGenerationTools>;
"}

