import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useLocalization } from '@/context/LocalizationContext';
import type { ReportGenerationToolsController } from '@/hooks/report-mode/use-report-generation-tools';
import { Chapter, Section } from '@/lib/types';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { FolderTree, PlusCircle, Sparkles } from 'lucide-react';
import { SectionAccordionItem } from './SectionAccordionItem';
import { SortableChapterItem } from './SortableChapterItem';

interface GenerationToolsProps {
  activeSectionId: string | null;
  onActiveSectionChange: (sectionId: string | null) => void;
  controller: ReportGenerationToolsController;
}

export default function GenerationTools({
  activeSectionId,
  onActiveSectionChange,
  controller,
}: GenerationToolsProps) {
  const { t } = useLocalization();
  const {
    project,
    handleAddChapter,
    handleAddSection,
    handleDragEnd,
    isProjectBuildMode,
    selectedSectionsForBuild,
    selectedSectionsCount,
    totalSelectableSections,
    toggleChapterSelection,
    toggleSectionSelection,
  } = controller;

  if (!project) return null;

  const chapterCount = project.chapters.length;
  const sectionCount = project.sections.length;
  const contentItems = project.content || [];

  const handleActivateSection = (sectionId: string) => {
    onActiveSectionChange(sectionId);
  };

  return (
    <div className="flex h-full min-h-0 flex-col gap-4">
      <div className="rounded-xl border bg-background/80 p-4 shadow-sm">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div className="space-y-2">
            <div className="flex items-center gap-2 text-sm font-medium text-foreground">
              <FolderTree className="h-4 w-4 text-primary" />
              <span>{t('builder.reportGenerator.toolsTitle')}</span>
            </div>
            <p className="text-sm text-muted-foreground">
              Organize your project outline, select a section to edit, and manage build selections from the right sidebar.
            </p>
            <div className="flex flex-wrap gap-2 text-xs text-muted-foreground">
              <span className="rounded-full border bg-muted/40 px-2.5 py-1">{chapterCount} chapters</span>
              <span className="rounded-full border bg-muted/40 px-2.5 py-1">{sectionCount} sections</span>
              {isProjectBuildMode && (
                <span className="rounded-full border border-primary/20 bg-primary/10 px-2.5 py-1 text-primary">
                  {selectedSectionsCount}/{totalSelectableSections} selected for build
                </span>
              )}
            </div>
          </div>
          <Button onClick={handleAddChapter} className="w-full sm:w-auto">
            <PlusCircle className="me-2 h-4 w-4" />
            Add Chapter
          </Button>
        </div>
      </div>

      {isProjectBuildMode && (
        <div className="rounded-xl border border-primary/20 bg-primary/5 px-4 py-3 text-sm text-muted-foreground">
          Select the sections you want to include in the project build from the outline below. Final build controls are available in the right sidebar.
        </div>
      )}

      <div className="min-h-0 flex-1 rounded-xl border bg-background shadow-sm">
        {contentItems.length === 0 ? (
          <div className="flex h-full flex-col items-center justify-center gap-4 p-8 text-center">
            <div className="rounded-full bg-primary/10 p-3 text-primary">
              <Sparkles className="h-5 w-5" />
            </div>
            <div className="space-y-1">
              <h3 className="text-base font-semibold">Start building your report outline</h3>
              <p className="max-w-md text-sm text-muted-foreground">
                Add your first chapter to create a structure for sections, prompts, and generation controls.
              </p>
            </div>
            <Button onClick={handleAddChapter}>
              <PlusCircle className="me-2 h-4 w-4" />
              Add First Chapter
            </Button>
          </div>
        ) : (
          <ScrollArea className="h-full">
            <div className="space-y-4 p-4">
              <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                <SortableContext items={contentItems.map((item) => item.id)} strategy={verticalListSortingStrategy}>
                  {contentItems.map((item, index) => {
                    if (item instanceof Chapter) {
                      return (
                        <SortableChapterItem
                          key={item.id}
                          chapter={item}
                          index={index}
                          isProjectBuildMode={isProjectBuildMode}
                          selectedSectionsForBuild={selectedSectionsForBuild}
                          toggleChapterSelection={toggleChapterSelection}
                          toggleSectionSelection={toggleSectionSelection}
                          activeSectionId={activeSectionId}
                          onActivateSection={handleActivateSection}
                          onAddSection={handleAddSection}
                        />
                      );
                    }

                    if (item instanceof Section) {
                      return (
                        <SectionAccordionItem
                          key={item.id}
                          section={item}
                          sectionIndex={index}
                          chapterIndex={-1}
                          isProjectBuildMode={isProjectBuildMode}
                          isSelected={selectedSectionsForBuild.has(item.id)}
                          toggleSectionSelection={toggleSectionSelection}
                          isActive={activeSectionId === item.id}
                          onActivate={handleActivateSection}
                        />
                      );
                    }

                    return null;
                  })}
                </SortableContext>
              </DndContext>
            </div>
          </ScrollArea>
        )}
      </div>
    </div>
  );
}
"}

