import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { cn } from '@/lib/utils/cn';
import { Chapter } from '@/lib/types';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical, Layers3, PlusCircle } from 'lucide-react';
import React, { useMemo } from 'react';
import { SectionAccordionItem } from './SectionAccordionItem';

interface SortableChapterItemProps {
  chapter: Chapter;
  index: number;
  isProjectBuildMode: boolean;
  selectedSectionsForBuild: Set<string>;
  toggleChapterSelection: (chapterId: string, select: boolean) => void;
  toggleSectionSelection: (sectionId: string) => void;
  activeSectionId: string | null;
  onActivateSection: (sectionId: string) => void;
  onAddSection: (chapterId: string) => void;
}

export function SortableChapterItem({
  chapter,
  index,
  isProjectBuildMode,
  selectedSectionsForBuild,
  toggleChapterSelection,
  toggleSectionSelection,
  activeSectionId,
  onActivateSection,
  onAddSection,
}: SortableChapterItemProps) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: chapter.id });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 2 : 0,
    position: 'relative',
  };

  const sectionsInChapter = chapter.sections;
  const selectedCount = useMemo(
    () => sectionsInChapter.filter((section) => selectedSectionsForBuild.has(section.id)).length,
    [sectionsInChapter, selectedSectionsForBuild]
  );
  const isAllSectionsSelected = sectionsInChapter.length > 0 && selectedCount === sectionsInChapter.length;
  const isSomeSectionsSelected = selectedCount > 0 && !isAllSectionsSelected;

  return (
    <div ref={setNodeRef} style={style} {...attributes}>
      <div className={cn('rounded-xl border bg-background shadow-sm transition-shadow', isDragging && 'shadow-md')}>
        <div className="flex flex-col gap-3 border-b bg-muted/10 px-4 py-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex min-w-0 items-start gap-3">
            {isProjectBuildMode && (
              <div className="pt-0.5">
                <Checkbox
                  id={`select-chapter-${chapter.id}`}
                  checked={isAllSectionsSelected}
                  aria-checked={isSomeSectionsSelected ? 'mixed' : isAllSectionsSelected}
                  onCheckedChange={(checked) => toggleChapterSelection(chapter.id, !!checked)}
                  aria-label={`Select all sections in chapter ${chapter.title}`}
                />
              </div>
            )}
            <div {...listeners} className="flex shrink-0 cursor-grab touch-none items-center gap-2 rounded-md p-1.5 text-muted-foreground transition-colors hover:bg-muted/50">
              <span className="w-5 text-center text-xs font-semibold">{index + 1}</span>
              <GripVertical className="h-4 w-4" />
            </div>
            <div className="min-w-0 space-y-1">
              <div className="flex flex-wrap items-center gap-2">
                <h3 className="truncate text-sm font-semibold sm:text-base">{chapter.title}</h3>
                <span className="rounded-full border bg-background px-2 py-0.5 text-[11px] text-muted-foreground">
                  {sectionsInChapter.length} sections
                </span>
                {isProjectBuildMode && selectedCount > 0 && (
                  <span className="rounded-full border border-primary/20 bg-primary/10 px-2 py-0.5 text-[11px] text-primary">
                    {selectedCount} selected
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <Layers3 className="h-3.5 w-3.5" />
                <span>Organize and activate sections from this chapter.</span>
              </div>
            </div>
          </div>

          <Button size="sm" variant="outline" onClick={() => onAddSection(chapter.id)} className="w-full sm:w-auto">
            <PlusCircle className="me-2 h-4 w-4" />
            Add Section
          </Button>
        </div>

        <div className="space-y-2 px-4 py-4">
          {sectionsInChapter.length === 0 ? (
            <div className="rounded-lg border border-dashed bg-muted/20 px-4 py-5 text-sm text-muted-foreground">
              <p className="font-medium text-foreground">No sections yet</p>
              <p className="mt-1">Add a section to start writing prompts, controls, and context for this chapter.</p>
            </div>
          ) : (
            sectionsInChapter.map((section, sectionIndex) => (
              <SectionAccordionItem
                key={section.id}
                section={section}
                sectionIndex={sectionIndex}
                chapterIndex={index}
                isProjectBuildMode={isProjectBuildMode}
                isSelected={selectedSectionsForBuild.has(section.id)}
                toggleSectionSelection={toggleSectionSelection}
                isActive={activeSectionId === section.id}
                onActivate={onActivateSection}
              />
            ))
          )}
        </div>
      </div>
    </div>
  );
}
"}

