import { GripVertical, Link as LinkIcon, Loader2 } from 'lucide-react';
import React from 'react';

interface SectionAccordionItemProps {
  section: Section;
  chapterIndex: number;
  sectionIndex: number;
  isProjectBuildMode: boolean;
  isSelected: boolean;
  isActive: boolean;
  onActivate: (sectionId: string) => void;
  toggleSectionSelection: (sectionId: string) => void;
}

export function SectionAccordionItem({
  section,
  chapterIndex,
  sectionIndex,
  isProjectBuildMode,
  isSelected,
  isActive,
  onActivate,
  toggleSectionSelection,
}: SectionAccordionItemProps) {
  const { project } = useBuilderStore();
  const { generateSectionMutation } = useAiActions();

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: section.id });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 2 : 0,
    position: 'relative',
  };

  const isGenerating = generateSectionMutation?.isPending && generateSectionMutation.variables === section.id;

  const getContextNames = (proj: Project | null, sec: Section): string[] => {
    if (!proj || !sec.context) return [];

    const sectionNames = Object.keys(sec.context.sections || {}).map((id) => proj.getSection(id)?.title || 'Untitled Section');
    const fileNames = Object.keys(sec.context.externalContext || {}).map((id) => proj.externalContext?.find((file) => file.id === id)?.fileName || 'Untitled File');

    return [...sectionNames, ...fileNames];
  };

  const contextNames = getContextNames(project, section);
  const totalContext = contextNames.length;

  return (
    <div ref={setNodeRef} style={style} {...attributes}>
      <div
        className={cn(
          'rounded-lg border bg-background transition-all',
          isDragging && 'shadow-md',
          isActive && 'border-primary/40 bg-primary/5 shadow-sm ring-1 ring-primary/20',
          isProjectBuildMode && isSelected && !isActive && 'border-emerald-200 bg-emerald-50/70 dark:border-emerald-900 dark:bg-emerald-950/20'
        )}
      >
        <div
          className={cn(
            'flex cursor-pointer flex-wrap items-center gap-3 px-3 py-3 sm:px-4',
            isActive && 'before:absolute before:inset-y-2 before:start-0 before:w-1 before:rounded-e-full before:bg-primary'
          )}
          onClick={() => onActivate(section.id)}
        >
          {isProjectBuildMode && (
            <div
              className="flex items-center gap-2"
              onClick={(event) => {
                event.stopPropagation();
                toggleSectionSelection(section.id);
              }}
            >
              <Checkbox checked={isSelected} aria-label={`Select section ${section.title}`} />
            </div>
          )}

          <div
            {...listeners}
            className="flex shrink-0 cursor-grab touch-none items-center gap-2 rounded-md p-1.5 text-muted-foreground transition-colors hover:bg-muted/50"
          >
            <span className="w-8 text-[11px] text-left font-medium">
              {chapterIndex >= 0 ? `${chapterIndex + 1}.${sectionIndex + 1}` : `${sectionIndex + 1}`}
            </span>
            <GripVertical className="h-4 w-4" />
          </div>

          <div className="min-w-0 flex-1 space-y-1">
            <div className="flex flex-wrap items-center gap-2">
              {isGenerating && <Loader2 className="h-4 w-4 animate-spin text-primary" />}
              <span className="truncate text-sm font-medium text-foreground">{section.title}</span>
              {isActive && (
                <span className="rounded-full border border-primary/20 bg-primary/10 px-2 py-0.5 text-[11px] text-primary">
                  Editing
                </span>
              )}
              {isProjectBuildMode && isSelected && (
                <span className="rounded-full border border-emerald-200 bg-emerald-100 px-2 py-0.5 text-[11px] text-emerald-700 dark:border-emerald-900 dark:bg-emerald-950/40 dark:text-emerald-300">
                  Selected
                </span>
              )}
            </div>
            <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
              <span>Click to open this section in the right sidebar</span>
              {totalContext > 0 && (
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <div className="flex items-center gap-1 rounded-full border border-primary/20 bg-primary/10 px-2 py-0.5 text-primary">
                        <LinkIcon className="h-3.5 w-3.5" />
                        <span className="font-medium">{totalContext} linked</span>
                      </div>
                    </TooltipTrigger>
                    <TooltipContent side="top">
                      <div className="space-y-1 text-xs">
                        {contextNames.map((name) => (
                          <p key={name}>{name}</p>
                        ))}
                      </div>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
"}

